select *
from village_homestay


        and village_id = #{villageId}


        and homestay_name like concat('%', #{homestayName}, '%')


        and address like concat('%', #{address}, '%')


        and status = #{status}


        and star_level = #{starLevel}


        and contact_name like concat('%', #{contactName}, '%')


order by id asc

